// Ancla de "hoy" para la demo (coincide con la fecha actual)
const HOY = new Date("2026-08-14T09:00:00");

function diasHasta(fechaStr) {
  if (!fechaStr) return null;
  const f = new Date(fechaStr + "T09:00:00");
  const diff = Math.round((f - HOY) / (1000 * 60 * 60 * 24));
  return diff;
}

function normalizar(txt) {
  return (txt || "")
    .toString()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, ""); // saca tildes/acentos
}

function formatFecha(fechaStr) {
  if (!fechaStr) return "—";
  const f = new Date(fechaStr + "T09:00:00");
  return f.toLocaleDateString("es-AR", { day: "numeric", month: "short" });
}

