// Sonido corto tipo "campanita", sin archivos externos (Web Audio API)
function reproducirSonido() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const notas = [880, 1108];
    notas.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type = "sine";
      osc.frequency.value = freq;
      const inicio = ctx.currentTime + i * 0.14;
      gain.gain.setValueAtTime(0.0001, inicio);
      gain.gain.exponentialRampToValueAtTime(0.2, inicio + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, inicio + 0.3);
      osc.start(inicio);
      osc.stop(inicio + 0.32);
    });
  } catch {
    // el navegador puede bloquear audio sin interacción previa; se ignora en silencio
  }
}

function soloDigitos(tel) {
  return tel.replace(/[^\d]/g, "");
}

