function urgenciaNivel(dias) {
  if (dias === null || dias === undefined) return null;
  if (dias <= 1) return "critica";
  if (dias <= 3) return "alta";
  if (dias <= 7) return "media";
  return null;
}

function EstadoChip({ estado, size = "sm" }) {
  const s = ESTADO_STYLE[estado] || ESTADO_STYLE["En trámite"];
  return (
    <span
      style={{ background: s.bg, color: s.fg }}
      className={`inline-flex items-center gap-1.5 rounded-full font-medium whitespace-nowrap ${
        size === "sm" ? "px-2.5 py-1 text-xs" : "px-3 py-1.5 text-sm"
      }`}
    >
      <span style={{ background: s.dot }} className="w-1.5 h-1.5 rounded-full" />
      {estado}
    </span>
  );
}

function VencimientoBadge({ exp, compact }) {
  const dias = diasHasta(exp.vencimiento);
  if (dias === null) return null;
  const nivel = urgenciaNivel(dias);
  const texto =
    dias < 0 ? `Venció hace ${Math.abs(dias)}d` :
    dias === 0 ? "Vence hoy" :
    dias === 1 ? "Vence mañana" :
    `En ${dias} días`;

  const palette = {
    critica: { bg: "#FBE4DF", fg: "#B8482E", ring: "#E8836A" },
    alta: { bg: "#FCEFDA", fg: "#A06A1E", ring: "#E0A954" },
    media: { bg: "#FBF3E0", fg: "#8A6A28", ring: "#D6B876" },
  };
  const p = palette[nivel] || { bg: "#F1EFE8", fg: "#8A9482", ring: "transparent" };
  const pulsar = nivel === "critica" || nivel === "alta";

  return (
    <div
      style={{ background: p.bg, color: p.fg }}
      className={`inline-flex items-center gap-1.5 rounded-lg font-medium ${compact ? "text-[12px] px-2 py-1" : "text-[13px] px-2.5 py-1.5"}`}
    >
      <span className="relative flex h-2 w-2">
        {pulsar && (
          <span
            style={{ background: p.ring }}
            className="animate-ping absolute inline-flex h-full w-full rounded-full opacity-75"
          />
        )}
        <span style={{ background: p.ring }} className="relative inline-flex rounded-full h-2 w-2" />
      </span>
      {exp.vencimientoLabel ? `${exp.vencimientoLabel} · ${texto}` : texto}
    </div>
  );
}

function CaseCard({ exp, onClick, onQuickEstado, favorito, onToggleFavorito }) {
  const [editando, setEditando] = useState(false);
  const dias = diasHasta(exp.vencimiento);
  const nivel = urgenciaNivel(dias);
  const ringClass =
    nivel === "critica" ? "border-[#E8836A] shadow-[0_0_0_1px_#F5C3B2]" :
    nivel === "alta" ? "border-[#E0A954]" :
    "border-[#DDE7E6]";

  return (
    <button
      onClick={() => onClick(exp)}
      className={`w-full text-left bg-white rounded-2xl border ${ringClass} hover:shadow-md transition-all duration-150 overflow-hidden active:scale-[0.99]`}
    >
      <div className="flex items-center justify-between px-4 pt-3 gap-2">
        <div className="flex items-center gap-1.5 min-w-0">
          <button
            onClick={(e) => { e.stopPropagation(); onToggleFavorito(exp.id); }}
            title={favorito ? "Quitar de fijados" : "Fijar arriba"}
            className="shrink-0 p-0.5"
          >
            <Star
              size={16}
              fill={favorito ? "#C79A44" : "none"}
              color={favorito ? "#C79A44" : "#B7C4AE"}
            />
          </button>
          <span
            className="text-[13px] tracking-wide px-2.5 py-1 rounded-md bg-[#E7F2F1] text-[#1D5854] shrink-0"
            style={{ fontFamily: "'Cormorant Garamond', serif", fontWeight: 600 }}
          >
            N.º {exp.id}
          </span>
        </div>
        {editando ? (
          <select
            autoFocus
            value={exp.estado}
            onClick={(e) => e.stopPropagation()}
            onChange={(e) => {
              onQuickEstado(exp.id, e.target.value);
              setEditando(false);
            }}
            onBlur={() => setEditando(false)}
            className="text-[12px] font-medium rounded-full px-2 py-1 border border-[#4FA39D] bg-white text-[#1D5854] focus:outline-none"
          >
            {ESTADOS.filter((s) => s !== "Todos").map((s) => (
              <option key={s} value={s}>{s}</option>
            ))}
          </select>
        ) : (
          <span
            onClick={(e) => { e.stopPropagation(); setEditando(true); }}
            title="Tocar para cambiar el estado"
          >
            <EstadoChip estado={exp.estado} />
          </span>
        )}
      </div>

      <div className="px-4 pb-3 pt-2">
        <h3
          className="text-[#33281A] text-[16.5px] font-medium leading-snug mb-0.5"
          style={{ fontFamily: "'Cormorant Garamond', serif" }}
        >
          {exp.caratula}
        </h3>
        <p className="text-[12.5px] text-[#8A8272] mb-2">{exp.fuero}</p>
        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-[13px] text-[#6B7A78]">
          <span className="inline-flex items-center gap-1">
            <FolderOpen size={13} /> {exp.tipo}
          </span>
          <span className="inline-flex items-center gap-1">
            <User size={13} /> {exp.responsable}
          </span>
          {exp.notas && (
            <span className="inline-flex items-center gap-1 text-[#8A6A28]">
              <StickyNote size={13} />
            </span>
          )}
        </div>
        <div className="flex items-center justify-between mt-2.5">
          {exp.vencimiento ? (
            <VencimientoBadge exp={exp} compact />
          ) : (
            <span />
          )}
          <ContactoIconos exp={exp} />
        </div>
      </div>
    </button>
  );
}

